sys_sg_write_back_action_item.execution_script:
// Issue Material via existing Operator API contract
var pmId = inputs.production_material_id;
var issueQty = parseFloat(inputs.issue_quantity) || 0;

// Input validation
if (!pmId) { output.error = "Production Material ID is required."; }
else if (isNaN(issueQty) || issueQty <= 0) { output.error = "Issue Quantity must be a positive number."; }
else {
  // Call existing issue-material API via internal REST
  var sm = new sn_ws.RESTMessageV2();
  sm.setHttpMethod("POST");
  sm.setEndpoint(gs.getProperty("glide.servlet.uri") + "api/x_2056099_indust_0/operator_api/issue-material");
  sm.setRequestHeader("Content-Type", "application/json");
  sm.setRequestHeader("Accept", "application/json");
  sm.setRequestBody(JSON.stringify({
    production_material_id: pmId,
    issue_quantity: issueQty
  }));
  try {
    var resp = sm.execute();
    var statusCode = resp.getStatusCode();
    var body = JSON.parse(resp.getBody());
    if (statusCode == 200 && body.result && body.result.success) {
      output.success = true;
      output.message = body.result.message || "Material issued successfully.";
    } else {
      output.error = (body.result && body.result.error) || (body.error && body.error.message) || "Issue failed (HTTP " + statusCode + ")";
    }
  } catch(e) {
    output.error = "API call failed: " + e.message;
  }
}
